using System;
using System.Collections.Generic;

class Program
{
    static int FindMax(int[] numbers)
    {
        int biggest = numbers[0];
        foreach (int x in numbers)
        {
            if (x > biggest)
            {
                biggest = x;
            }
        }
        return biggest;
    }
}

