using System;
using System.Collections.Generic;

class Program
{
    static int[] RemoveDuplicates(int[] items)
    {
        List<int> result = new List<int>();
        foreach (int x in items)
        {
            if (!result.Contains(x))
            {
                result.Add(x);
            }
        }
        return result.ToArray();
    }
}

