using System;
using System.Collections.Generic;

class Program
{
    static int[] Top3(int[] numbers)
    {
        List<int> sorted = new List<int>(numbers);
        sorted.Sort();
        sorted.Reverse();
        int howMany = Math.Min(3, sorted.Count);
        return sorted.GetRange(0, howMany).ToArray();
    }
}
